}

//+------------------------------------------------------------------+
//| Verifica condições de compra                                      |
//+------------------------------------------------------------------+
bool CheckBuyCondition(double ema_value)
{
   if (Close[1] < ema_value && Close[0] > ema_value) 
      return true;
   return false;
}

//+------------------------------------------------------------------+
//| Verifica condições de venda                                       |
//+------------------------------------------------------------------+
bool CheckSellCondition(double ema_value)
{
   if (Close[1] > ema_value && Close[0] < ema_value) 
      return true;
   return false;
}

//+------------------------------------------------------------------+
//| Função para o OnTick                                              |
//+------------------------------------------------------------------+
void OnTick()
{
   if (Symbol() != "XAUUSD") return;

