   double current_ema = GetEMAValue(EMA_Period, 0);

   // --- LÓGICA DE TRADING ---

   // Compra
   if (CheckBuyCondition(current_ema) && OrdersTotal() == 0)
   {
      // Encontrar o menor preço dos últimos 10 candles para o SL dinâmico
      double lowest_price = iLow(NULL, 0, 10, MODE_LOW, 1);

      // Cálculo do TP baseado na distância do SL encontrado
      double tp_distance = (Close[0] - lowest_price) * Risk_Reward_Ratio;
      double take_profit_buy = Close[0] + tp_distance;

      double stop_loss_buy = lowest_price; // Usando o low real como SL

      int buy_ticket = OrderSend(Symbol(), OP_BUY, Lots, Ask, slippage, stop_loss_buy, take_profit_buy, "Buy order", 0, 0, clrGreen);
      if(buy_ticket < 0)
      {
         Print("Erro ao abrir a ordem de compra: ", GetLastError());
      }
   }

   // Venda
   if (CheckSellCondition(current_ema) && OrdersTotal() == 0)
   {
      // Encontrar o maior preço dos últimos 10 candles para o SL dinâmico
      double highest_price = iHigh(NULL, 0, 10, MODE_HIGH, 1);

      // Cálculo do TP baseado na distância do SL encontrado
      double tp_distance = (highest_price - Close[0]) * Risk_Reward_Ratio;
      double take_profit_sell = Close[0] - tp_distance;

      double stop_loss_sell = highest_price; // Usando o high real como SL

      int sell_ticket = OrderSend(Symbol(), OP_SELL, Lots, Bid, slippage, stop_loss_sell, take_profit_sell, "Sell order", 0, 0, clrRed);
      if(sell_ticket < 0)
      {
         Print("Erro ao abrir a ordem de venda: ", GetLastError());
      }
   }
}

//+------------------------------------------------------------------+
//| Função para iniciar o robô                                        |
//+------------------------------------------------------------------+
void OnInit()
{
   if (Symbol() != "XAUUSD")
   {
      Print("Este robô foi projetado para operar apenas no ativo XAUUSD.");
      return;
