   ema_object_handle = ObjectCreate(0, "EMA_Blue_Line", OBJ_TREND, 0, Time[0], 0, Time[0], 0);

   if(ema_object_handle == INVALID_HANDLE)
   {
      Print("Falha ao criar o objeto da EMA.");
      return;
