   ObjectSetInteger(0, "EMA_Blue_Line", OBJPROP_COLOR, clrBlue);
   ObjectSetInteger(0, "EMA_Blue_Line", OBJPROP_STYLE, STYLE_SOLID);
   ObjectSetInteger(0, "EMA_Blue_Line", OBJPROP_WIDTH, 2);
   ObjectSetInteger(0, "EMA_Blue_Line", OBJPROP_BACK, FALSE); // Fundo transparente
   ObjectSetInteger(0, "EMA_Blue_Line", OBJPROP_HIDDEN, FALSE);

   // Atualizar os dados visuais com o valor atual da EMA
   // Isso faz com que a linha apareça corretamente sobre os dados históricos
   double last_ema = GetEMAValue(EMA_Period, 0);
   ObjectSetDouble(0, "EMA_Blue_Line", 0, last_ema);
}

